{
 "research_concepts": ["lineup effects", "offensive five personnel", "shot mix", "substitution-based within-game variation", "matchup effects", "positive-control validation of a design"],
 "methodological_questions": [
  "Does a within-game change of the offensive five shift shot-type mix (rim, 3PA, mid-range, FT-generating actions) relative to stints where the five is unchanged?",
  "Can the design separate a personnel effect from shooter, game-state, and coach-selected substitution confounds?",
  "Is the design sensitive enough, at the stated sample size and label quality, to detect a pre-specified minimal shot-mix shift?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF34",
   "status_as_recorded": "inconclusive",
   "finding": "Opponent lineup study (rim big off floor). CHT-075 reports DRIVE +0.82pp (SE 0.25, t=+3.3), POST_UP +0.43pp (SE 0.18), 3PA -1.79pp (SE 0.31, t=-5.8), PPP +0.008 (SE 0.007, t=+1.1) on N=1.07M possessions. Chat verdict recorded as WEAK/SMALL and not carrying a paper. Limited by small_sample."
  },
  {
   "id": "FAM:SF-TMP-009",
   "status_as_recorded": "artifact",
   "finding": "PULL_UP exposure-decline diagnostics. Slope with lineup FE -0.0255 (SE 0.0061) shrinks to -0.0063 (SE 0.0036) without lineup FE; same-shooter placebo on other play types -0.0075 (SE 0.0017). Verdict recorded as artifact_found, attributed to a shooter-level confound."
  },
  {
   "id": "FAM:SF-CHT-076",
   "status_as_recorded": "artifact",
   "finding": "Bonus-threshold and foul-trouble-big adaptation. Bonus FTA +5.08pp is mechanical from the rulebook; DRIVE +0.31pp matches the 2-3 placebo +0.33pp. Foul-trouble-big exposure is 1.44% of possessions because coaches bench the player."
  },
  {
   "id": "FAM:SF-PAP-042",
   "status_as_recorded": "rejected",
   "finding": "No systematic pivots when a better same-game option exists: 1,466/1,539 (95.3%) had a better option, zero significant pivots in the paper analysis, n=1,539 triggers. Recorded as an adequately powered null (B_powered_null)."
  },
  {
   "id": "FAM:SF38",
   "status_as_recorded": "inconclusive",
   "finding": "Defensive adaptation to repeated play type. League-wide within-game slope -0.0019 PPP/exposure (SE 0.0019); only PULL_UP survives Holm (-0.0243, holm 0.0004). Team-trait split-half r +0.008. Limited by insufficient_exposure, label_or_classification_error, and low_measurement_reliability."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Defensive scheme change using inferred labels: within-game change 61.0%, cross-game 67.7%, transition matrices near-uniform. Doc caveat: the inferred label cannot separate defensive adjustment from offense executing differently."
  },
  {
   "id": "FAM:SF-APPS-058",
   "status_as_recorded": "untestable",
   "finding": "On-ball scheme labels (DROP/ICE/SWITCH) from NBA matchup/PBP fields: 14.9% labeled for DET and 3.3% for ORL; switches_on field unpopulated. Verdict recorded as failed_gate."
  },
  {
   "id": "FAM:SF-TMP-016",
   "status_as_recorded": "untestable",
   "finding": "Team heterogeneity in halftime play-type adaptation: heterogeneity variance not above the permutation null (p=0.363); split-half r -0.026 across 120 team-seasons; team-season slope SD 0.6733 vs mean sampling SE 0.6508."
  },
  {
   "id": "FAM:SF-APPM-021",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Descriptive play-type mix shifts by halftime margin, crunch time and post-run; no inferential tests; OTHER label known to be noisy (PT audit)."
  },
  {
   "id": "FAM:SF-TMP-023",
   "status_as_recorded": "not a hypothesis test",
   "finding": "After-timeout play-type shift: POST_UP +2.406 and SPOT_UP +2.333 vs same game-offense-period-minute on 56,423 ATO possessions; half-court PPP -0.0105 (SE 0.0056). Descriptive only."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-TMP-009",
   "what_failed": "Attributing a PULL_UP decline with exposure to defensive adaptation using lineup-FE slopes",
   "why": "Recorded as artifact_found: effect shrinks from -0.0255 to -0.0063 without lineup FE, and same-shooter placebo on other play types is of similar size. Limited by confounding."
  },
  {
   "id": "FAM:SF-CHT-076",
   "what_failed": "Treating bonus-threshold and foul-trouble-big shot-mix changes as strategic adaptation",
   "why": "Recorded as artifact: FTA jump is mechanical from the rulebook, DRIVE matches the placebo, and the foul-trouble exposure is too sparse (1.44%) because of coach benching. Limited by insufficient_exposure."
  },
  {
   "id": "FAM:SF-APPS-058",
   "what_failed": "Deriving on-ball coverage labels from NBA matchup/PBP fields",
   "why": "Recorded as failed_gate: label rates of 14.9% and 3.3%, and switches_on was not populated. Limited by label_or_classification_error and small_sample."
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Inferring defensive scheme changes from play-by-play labels",
   "why": "Recorded as untestable: near-uniform transition matrices consistent with label noise; the label cannot separate defense from offensive execution."
  },
  {
   "id": "FAM:SF-TMP-016",
   "what_failed": "Estimating reliable team-level heterogeneity in play-type adaptation",
   "why": "Recorded as untestable/null: heterogeneity variance is indistinguishable from the permutation null, and split-half reliability is near zero. Limited by low_measurement_reliability."
  }
 ],
 "evidence_establishes": [
  "Within this project's records, opponent-lineup changes (SF34, CHT-075/TMP-020) produce detectable group-level shot-mix shifts, for example a 3PA share change of -1.79pp (t=-5.8) on about 1.07M possessions. This is the closest record to a personnel-driven shot-mix effect, though its status is recorded as inconclusive.",
  "Several records show that naive lineup-level or game-state slopes are vulnerable to shooter-level and mechanical confounds (SF-TMP-009, SF-CHT-076), which bears directly on any own-five design.",
  "Label-dependent outcomes (play type, scheme, on-ball coverage) have been unreliable in this project's data (SF-APPS-058, SF-APPA-005, SF-APPM-021), so shot-type mix derived from play-by-play needs an explicit label audit.",
  "Small team-level or lineup-level samples have produced low reliability (SF-TMP-016, SF38), so power must be assessed at the level of the estimand."
 ],
 "evidence_does_not_establish": [
  "No retrieved record tests whether changing the offensive five itself moves shot mix. SF34 concerns the opposing lineup, and the query-level positive-control claim is not tested in any record.",
  "No record provides a power calculation for a within-game own-five substitution design; the sample and power field is NOT_RECORDED in several records.",
  "No record shows the validity of the 2022-23 to 2024-25 derived play-type labels or of substitution-interval reconstruction for this purpose.",
  "No record establishes that a null result would be informative about the design's sensitivity."
 ],
 "own_inferences": [
  "The question as posed presupposes its own answer. A positive result would confirm the effect; a null would be ambiguous between no effect and insufficient sensitivity. The test must be framed around a pre-specified minimal detectable effect.",
  "Substitutions are endogenous: coaches sub on matchup, fatigue, foul trouble, score and timeouts, so the shot-mix change after a sub conflates personnel with selection. SF-CHT-076 and SF-TMP-009 show that such selection can produce spurious results.",
  "The 3PA share effect in SF34 (-1.79pp) suggests that lineup composition can move shot mix at a magnitude that is plausibly detectable in a large sample, but this is an inference from an inconclusive record, not an established result.",
  "Within-game own-five changes are more frequent than opponent-big-off-floor states, so exposure sparsity is probably less severe for this estimand than in SF-CHT-076, but this is unverified."
 ],
 "uncertainties": [
  "Number of own-five substitution events per season and playoff segment in the stated data is unknown; no count was retrieved.",
  "Whether the rotation intervals and starters files reconstruct the on-court five accurately (including mid-possession changes) is not documented in the retrieved records.",
  "Whether shot-type labels (rim vs mid vs 3PA) from the play-by-play are reliable enough for a mix analysis is not established.",
  "Drift across 2022-23 to 2024-25 and between regular season and playoffs is not characterized; the playoff sample is small (SF-APPA-005 lists 52 series).",
  "Retrieval returned records but no follow-up tool was called; records beyond the ten returned were not read in full, and read_family was not used on SF34 or SF38 to check truncated results."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical records changed the decision from a simple 'proceed' to 'proceed_with_changes'. Records show that naive lineup and game-state slopes produced artifacts (SF-TMP-009, SF-CHT-076), that derived labels are unreliable (SF-APPS-058, SF-APPA-005), and that small-team samples have low reliability (SF-TMP-016). The design therefore needs placebo substitutions, label audits and a pre-specified power criterion. The positive-control framing is kept only as a test with a falsifiable minimal effect, not as a presupposed result."
 },
 "testability": {
  "p_testable": 0.55,
  "blocking_constraints": [
   {"code": "CONFOUNDING", "text": "Substitutions are selected by coaches on game state, fouls, matchups and fatigue; shot-mix changes after a sub may reflect these rather than the personnel change itself (SF-CHT-076, SF-TMP-009)."},
   {"code": "RTM_SELECTION", "text": "Own-five changes are non-random; the analysis must condition on the reason for the change or use within-stint placebo substitutions."},
   {"code": "LABEL_ERROR", "text": "Shot-type and play-type labels derived from play-by-play may be noisy (SF-APPM-021 OTHER noise; SF-APPA-005 near-uniform matrices)."},
   {"code": "OUTCOME_DERIVED_LABEL", "text": "Play-type labels in the graph database are derived from the play-by-play, which records outcomes; mix measures can be contaminated by the outcome they are compared with."},
   {"code": "SAMPLE_SIZE_POWER", "text": "Effects of about 1pp need large samples (SF34 used 1.07M possessions); per-team or per-lineup estimates are underpowered (SF-TMP-016)."}
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": ["FAM:SF34", "FAM:SF-TMP-009", "FAM:SF-CHT-076"],
  "summary": "SF34 addresses a related question (opposing rim-big off floor and offensive shot mix) with a recorded 3PA shift and inconclusive status. No retrieved record tests whether changing the offensive five itself moves shot mix, so the question as posed is not substantially answered. SF-TMP-009 and SF-CHT-076 show that the confounds (shooter FE, mechanical and selection effects) must be addressed before any lineup-level inference."
 },
 "risks": [
  {"code": "CONFOUNDING", "text": "Coach-selected substitutions tied to matchups, fouls and game state; shooter-level confound seen in SF-TMP-009."},
  {"code": "RTM_SELECTION", "text": "Changes made after a poor possession or a foul call may regress toward the mean and produce apparent shot-mix change."},
  {"code": "LABEL_ERROR", "text": "Play-type and shot labels are noisy; OTHER and inferred schemes are not reliable (SF-APPM-021, SF-APPA-005)."},
  {"code": "OUTCOME_DERIVED_LABEL", "text": "Derived play-type records use outcome information, so comparing mix to points risks circularity."},
  {"code": "SAMPLE_SIZE_POWER", "text": "Small effects need large samples; team- and lineup-level estimates have low reliability (SF-TMP-016, SF34)."},
  {"code": "PLACEBO_DEPENDENCE", "text": "Shooter or same-lineup placebos can absorb the effect; placebo results in SF-TMP-009 and SF-CHT-076 were close to the main estimate."},
  {"code": "MULTIPLE_TESTING", "text": "Several shot categories and game-state splits will generate many comparisons; SF38 survived only one play type under Holm."},
  {"code": "DRIFT_NONSTATIONARITY", "text": "Pooling 2022-23 to 2024-25 and playoffs may mix rule and style changes; the playoff sample is small."},
  {"code": "MEASURE_RELIABILITY", "text": "Stint-level shot-mix measures may have low reliability at the lineup level (SF38 and SF-TMP-016 show low reliability for team-level measures)."}
 ],
 "predicted_outcome": {
  "supported": 0.45,
  "rejected": 0.05,
  "untestable": 0.10,
  "artifact": 0.25,
  "uncertain": 0.15
 },
 "decision": "proceed_with_changes",
